def main():
    CATALOG_DIR.mkdir(parents=True, exist_ok=True)
    makes_dir = CATALOG_DIR / "makes"
    makes_dir.mkdir(parents=True, exist_ok=True)

    index_file = CATALOG_DIR / "makes_index.json"
    index_file.write_text(json.dumps({"makes": MAKES_MASTER}, indent=2, ensure_ascii=False), encoding="utf-8")

    created = 0
    for m in MAKES_MASTER:
        mfolder = makes_dir / m["make_slug"]
        mfolder.mkdir(parents=True, exist_ok=True)
        (mfolder / "models").mkdir(parents=True, exist_ok=True)
        mjson = mfolder / "make.json"
        if not mjson.exists():
            mjson.write_text(json.dumps(m, indent=2, ensure_ascii=False), encoding="utf-8")
            created += 1
    print(f"Seeded {len(MAKES_MASTER)} makes in makes_index.json ({created} new make.json files created).")

if __name__ == "__main__":
    main()
